# Team Arena - Symmetrical map for Team Deathmatch battles
name TeamArena
dimensions 60.0 15.0 60.0

# Main floor - thick to prevent phasing
block 0.0 -1.0 0.0 60.0 2.0 60.0 0 1 0

# Team A (Red) Base - Left side
# Platform
block -25.0 0.0 0.0 10.0 2.0 20.0 2 1 1 0.8 0.3 0.2

