# Team A (Red) Spawn Points
# Left side facing center (toward positive X)
team_spawn -25.0 1.0 -8.0 0 90.0 0.0
team_spawn -25.0 1.0 0.0 0 90.0 0.0
team_spawn -25.0 1.0 8.0 0 90.0 0.0
